mapper.update:
UPDATE im_conversation
SET last_msg      = #{lastMsg},
    last_msg_time = #{lastMsgTime},
    last_msg_type = #{lastMsgType}
WHERE id = #{conversationId}

mapper.select:
SELECT COUNT(*) FROM im_conversation c
WHERE (
    (c.type = 1 AND (c.participant_a = #{userId} OR c.participant_b = #{userId}))
    OR
    (c.type = 2 AND EXISTS (
        SELECT 1 FROM im_group_member gm
        WHERE gm.conversation_id = c.id AND gm.user_id = #{userId}
    ))
)
AND NOT EXISTS (
    SELECT 1 FROM user_block b
    WHERE c.type = 1
      AND (
          (b.blocker_id = #{userId}
           AND b.blocked_id = CASE WHEN c.participant_a = #{userId}
                                   THEN c.participant_b ELSE c.participant_a END)
          OR
          (b.blocked_id = #{userId}
           AND b.blocker_id = CASE WHEN c.participant_a = #{userId}
                                   THEN c.participant_b ELSE c.participant_a END)
      )
)

SELECT m.conversation_id AS convId, COUNT(*) AS cnt
FROM im_message m
LEFT JOIN im_read_cursor rc
    ON rc.conversation_id = m.conversation_id AND rc.user_id = #{userId}
WHERE m.conversation_id IN
#{id}
AND m.seq > COALESCE(rc.last_read_seq, 0)
AND m.sender_id != #{userId}
AND m.is_recalled = 0
GROUP BY m.conversation_id

SELECT * FROM im_conversation
WHERE participant_a = #{userId} OR participant_b = #{userId}
UNION
SELECT c.* FROM im_conversation c
JOIN im_group_member gm ON gm.conversation_id = c.id
WHERE gm.user_id = #{userId}

SELECT last_read_seq FROM im_read_cursor
WHERE conversation_id = #{convId} AND user_id = #{userId}
LIMIT 1
